// src/compiler/functions/sorted.ts
astParsingFunctions.sorted = function(content) {
  if (content.args[0].name === "__array__" && content.args[1].name === "__multiply__" && (content.args[1].args[0].name === "__number__" && content.args[1].args[0].args[0].numValue === -1 && content.args[1].args[1].name === "__currentArrayIndex__" || content.args[1].args[0].name === "__currentArrayIndex__" && content.args[1].args[1].name === "__number__" && content.args[1].args[1].args[0].numValue === -1)) {
    content.args[0].args.reverse();
    return content.args[0];
  }
  content.name = "__sortedArray__";
  content.type = content.args[0].type;
  return content;
};

// src/compiler/functions/spacesForLength.ts
astParsingFunctions.spacesForLength = function(content) {
  console.log(content);
  if (content.args[0].name !== "__number__") {
    error("Length must be a literal number", content.args[0].fileStack);
  }
  let length = content.args[0].args[0].numValue;
  return getAstForCustomString(
    getBestSpaces(Object.keys(spaces).map(Number), length).map((j) => spaces[j]).join("")
  );
};

// src/compiler/functions/spacesForString.ts
astParsingFunctions.spacesForString = function(content) {
  if (content.args[0].name === "__translatedString__") {
    return getAstForTranslatedString(content.args[0]);
  }
  return astParsingFunctions.spacesForLength(new Ast2("spacesForLength", [astParsingFunctions.strVisualLength(content)]));
};

// src/compiler/functions/splitDictArray.ts
astParsingFunctions.splitDictArray = function(content) {
  if (content.args[0].name !== "__dict__") {
    error("First argument of splitDictArray() must be a dictionary", content.args[0].fileStack);
  }
  if (content.args[1].name !== "__array__") {
    error("Second argument of splitDictArray() must be a literal array", content.args[1].fileStack);
  }
  for (let elem of content.args[1].args) {
    if (elem.name !== "__dict__") {
      error("Second argument of splitDictArray() must be a literal array of dictionaries", elem.fileStack);
    }
  }
  let variableKeys = content.args[0].args.map((x) => x.args[0].name);
  let variables = content.args[0].args.map((x) => x.args[1]);
  let arrays = Array(variableKeys.length).fill(0).map(() => getAstForEmptyArray());
  for (let dict of content.args[1].args) {
    let dictKeys = dict.args.map((x) => x.args[0].name);
    let dictValues = dict.args.map((x) => x.args[1]);
    for (let [i, key] of variableKeys.entries()) {
      if (!dict.args.some((x) => x.args[0].name === key)) {
        arrays[i].args.push(getAstForNull());
      } else {
        arrays[i].args.push(dictValues[dictKeys.findIndex((x) => x === key)]);
      }
    }
    for (let key of dictKeys) {
      if (!variableKeys.includes(key)) {
        error("Key '" + key + "' in dictionary is not defined in the first argument of splitDictArray()", dict.fileStack);
      }
    }
  }
  if (content.args[2].name === "true") {
    arrays = arrays.map((x) => {
      try {
        return astParsingFunctions.compressed(new Ast2("compressed", [x]));
      } catch (e) {
        return x;
      }
    });
  }
  let assignments = arrays.map((x, i) => new Ast2("__assignTo__", [variables[i], x]));
  if (!content.parent) {
    error("Could not find parent of splitDictArray");
  }
  content.parent.children.splice(content.parent.childIndex + 1, 0, ...assignments.slice(1));
  return assignments[0];
};

// src/compiler/functions/sqrt.ts
astParsingFunctions.sqrt = function(content) {
  if (enableOptimization) {
    if (content.args[0].name === "__number__") {
      return getAstForNumber(Math.sqrt(content.args[0].args[0].numValue) || 0);
    }
    if (content.args[0].name === "dotProduct" && areAstsAlwaysEqual(content.args[0].args[0], content.args[0].args[1])) {
      return new Ast2("magnitude", [content.args[0].args[0]]);
    }
  }
  return content;
};

